solution.solution.py:
from collections.abc import Callable


def first_or[T](items: list[T], default: T) -> T:
    return items[0] if items else default


def group_by[K, V](items: list[V], key: Callable[[V], K]) -> dict[K, list[V]]:
    groups: dict[K, list[V]] = {}
    for item in items:
        groups.setdefault(key(item), []).append(item)
    return groups

unitTests:
@test("first_or")
def _():
    check_eq(first_or([3, 4], 0), 3)
    check_eq(first_or([], "none"), "none")

@test("group_by keeps order inside groups")
def _():
    check_eq(group_by(["apple", "avocado", "banana"], lambda s: s[0]),
             {"a": ["apple", "avocado"], "b": ["banana"]})

@test("group_by with number keys")
def _():
    check_eq(group_by([1, 2, 3, 4, 5], lambda n: n % 2), {1: [1, 3, 5], 0: [2, 4]})

@test("group_by of nothing")
def _():
    check_eq(group_by([], len), {})

